WITH base AS ( SELECT td.t_hour AS hour_of_day, ws.ws_ship_mode_sk AS ship_mode, COUNT(DISTINCT cr.cr_order_number) AS num_returns, SUM(cr.cr_net_loss) AS total_return_loss, SUM(ws.ws_net_paid) AS total_sales_paid, CASE WHEN SUM(ws.ws_net_paid) = 0 THEN NULL ELSE SUM(cr.cr_net_loss) / SUM(ws.ws_net_paid) END AS loss_to_sales_ratio FROM catalog_returns cr JOIN time_dim td ON cr.cr_returned_time_sk = td.t_time_sk JOIN web_sales ws ON ws.ws_sold_time_sk = td.t_time_sk WHERE cr.cr_reason_sk IN (51, 50, 59) AND td.t_hour BETWEEN 9 AND 18 AND ws.ws_ship_mode_sk IN (1, 2, 3, 4, 5) GROUP BY td.t_hour, ws.ws_ship_mode_sk ) SELECT hour_of_day, ship_mode, num_returns, total_return_loss, total_sales_paid, loss_to_sales_ratio, RANK() OVER (PARTITION BY hour_of_day ORDER BY loss_to_sales_ratio DESC) AS loss_ratio_rank_in_hour FROM base ORDER BY hour_of_day, loss_to_sales_ratio DESC
